def single_number(nums):
    result = 0
    for num in nums:
        result ^= num
    return result

def count_valid_bits(n):
    count = 0
    while n:
        count += n & 1
        n >>= 1
    return count

class ListNode:
    def __init__(self, val=0, next=None):
        self.val = val
        self.next = next

def swap_pairs(head):
    if not head or not head.next:
        return head
    first = head
    second = head.next
    first.next = swap_pairs(second.next)
    second.next = first
    return second

